from pathlib import Path
import json,time
import numpy as np, geopandas as g, shapely
from shapely import STRtree
from shapely.ops import polygonize
out=Path('outputs/road_network_v2');out.mkdir(exist_ok=True)
def read(n):return g.read_file(f'data/raw/osm/gis_osm_{n}_free_1.shp').to_crs(32651)
city=g.read_file('data/raw/shanghai_boundary.geojson').to_crs(32651).geometry.union_all();x0,y0,x1,y1=city.bounds
roads=read('roads');roads=roads[roads.fclass.isin(['motorway','trunk','primary','secondary','tertiary','residential','unclassified','service','living_street'])&(roads.bridge!='T')&(roads.tunnel!='T')&(roads.layer.fillna(0)==0)].cx[x0:x1,y0:y1].explode(index_parts=False);roads=roads[roads.geom_type=='LineString'].reset_index(drop=True)
rail=read('railways');rail=rail[rail.fclass.isin(['rail','light_rail','tram'])&(rail.bridge!='T')&(rail.tunnel!='T')&(rail.layer.fillna(0)==0)].cx[x0:x1,y0:y1];water=read('water_a');water=water[water.fclass.isin(['water','riverbank','reservoir','dock'])].cx[x0:x1,y0:y1]
lines=roads.geometry.to_numpy();tree=STRtree(lines);l=shapely.length(lines);keep=l>1;lines=lines[keep];roads=roads.loc[keep].reset_index(drop=True);l=l[keep];tree=STRtree(lines)
start=shapely.line_interpolate_point(lines,0);end=shapely.line_interpolate_point(lines,1,normalized=True);points=np.concatenate([start,end]);src=np.tile(np.arange(len(lines)),2);nearstart=shapely.line_interpolate_point(lines,np.minimum(5,l/2));nearend=shapely.line_interpolate_point(lines,np.maximum(l-5,l/2));inside=np.concatenate([nearstart,nearend]);px=shapely.get_x(points);py=shapely.get_y(points);ux=px-shapely.get_x(inside);uy=py-shapely.get_y(inside);norm=np.hypot(ux,uy);ux=np.divide(ux,norm,out=np.zeros_like(ux),where=norm>0);uy=np.divide(uy,norm,out=np.zeros_like(uy),where=norm>0)
print('roads',len(lines),'endpoints',len(points),'querying nearby roads',flush=True);pair=tree.query(points,predicate='dwithin',distance=15);pi,ri=pair;mask=ri!=src[pi];pi=pi[mask];ri=ri[mask];d=shapely.distance(points[pi],lines[ri]);already=np.zeros(len(points),bool);already[pi[d<.2]]=True
valid=(d>=.2)&(d<=15)&~already[pi];pi=pi[valid];ri=ri[valid];d=d[valid];loc=shapely.line_locate_point(lines[ri],points[pi]);target=shapely.line_interpolate_point(lines[ri],loc);dx=shapely.get_x(target)-px[pi];dy=shapely.get_y(target)-py[pi];cos=np.divide(ux[pi]*dx+uy[pi]*dy,d,out=np.zeros_like(d),where=d>0);valid=cos>=np.cos(np.deg2rad(45));pi=pi[valid];ri=ri[valid];d=d[valid];target=target[valid]
order=np.lexsort((d,pi));pi=pi[order];ri=ri[order];d=d[order];target=target[order];first=np.r_[True,pi[1:]!=pi[:-1]];pi=pi[first];ri=ri[first];d=d[first];target=target[first];connectors=shapely.shortest_line(points[pi],target)
barriers=np.concatenate([rail.geometry.to_numpy(),water.geometry.to_numpy()]);barriertree=STRtree(barriers);hits=barriertree.query(connectors,predicate='intersects');blocked=np.zeros(len(connectors),bool);blocked[np.unique(hits[0])]=True
pi=pi[~blocked];ri=ri[~blocked];d=d[~blocked];connectors=connectors[~blocked];print('candidate connectors',len(connectors),'blocked',int(blocked.sum()),flush=True)
c=g.GeoDataFrame({'source_osm_id':roads.osm_id.iloc[src[pi]].to_numpy(),'target_osm_id':roads.osm_id.iloc[ri].to_numpy(),'gap_m':d,'type':'inferred_gap_closure'},geometry=connectors,crs=32651);c.to_file(out/'inferred_gap_connectors.gpkg',driver='GPKG')
w=shapely.make_valid(water.geometry.union_all());network=shapely.union_all(np.concatenate([lines,connectors,rail.geometry.to_numpy(),np.array([w.boundary,city.boundary],dtype=object)]));print('polygonizing',flush=True);shapely.prepare(city);faces=[p for p in polygonize(network) if p.area>.05 and city.covers(p.representative_point())];shapely.prepare(w);blocks=g.GeoDataFrame({'id':np.arange(len(faces),dtype='int32')},geometry=faces,crs=32651);blocks['is_water']=[w.covers(p.representative_point()) for p in faces];large=(~blocks.is_water)&(blocks.area>2e6);union=blocks.geometry.union_all();metrics={'input_roads':len(lines),'inferred_gap_connectors':len(connectors),'gap_max_m':15,'connector_median_m':float(np.median(d)) if len(d) else 0,'barrier_intersect_rejected':int(blocked.sum()),'faces':len(blocks),'large_land_faces':int(large.sum()),'large_land_area_km2':float(blocks.area[large].sum()/1e6),'gap_m2':float(city.difference(union).area),'overlap_m2':float(blocks.area.sum()-union.area),'invalid':int((~blocks.is_valid).sum())};print(json.dumps(metrics,indent=2),flush=True);blocks.to_file(out/'repaired_road_blocks.gpkg',driver='GPKG');(out/'repair_metrics.json').write_text(json.dumps(metrics,indent=2))
